css:
.container {
  width: 100%;
  height: 100%;
  --s: 6em;
  --d: 0.3em;
  --bg: #232228;
  --fg: rgb(90, 92, 102);
  background-color: var(--bg);
  background-image: radial-gradient(
      var(--d) var(--d) at 25% 25%,
      var(--fg) 100%,
      transparent 100%
    ),
    radial-gradient(
      var(--d) var(--d) at 75% 75%,
      var(--fg) 100%,
      transparent 100%
    );
  background-size: var(--s) calc(var(--s) * 0.577350269);
}
